lib/api/src/rest/schema.rs:22-42: pub(crate) fn validate_non_empty_dense(vector: &[f32]) -> Result<(), ValidationErrors> {
    if vector.is_empty() {
        let mut err = ValidationError::new("empty_vector");
        err.message = Some(Cow::Borrowed("dense vector must not be empty"));
        let mut errors = ValidationErrors::new();
        errors.add("vector", err);
        return Err(errors);
    }
    Ok(())
}
